widget_func='''function widgetCards(){const g=currentGoal(),today=todayTasks(),cd=state.countdowns.slice().sort((a,b)=>a.targetUtc-b.targetUtc)[0],latest=state.reviews.slice().sort((a,b)=>b.dateKey.localeCompare(a.dateKey))[0],done=completedToday().length,total=Math.max(1,today.length+done),mood=['','😞','🙁','😐','🙂','😄'][clamp(latest?.mood||3,1,5)];const q=[1,2,3,4].map(n=>state.tasks.filter(t=>!t.completed&&(t.quadrant||2)===n).length);return [['today',tr('Today','امروز'),`${digits(today.length)} ${tr('plans','برنامه')}`,today[0]?.title||tr('A calm day','یک روز آرام'),`✓ ${digits(done)}`],['focus',tr('Focus','تمرکز'),`${digits(focusMinutes(7))} ${tr('min','دقیقه')}`,tr('this week','این هفته'),'25 · 45 · 60'],['goal',tr('Goal','هدف'),`${digits(g?.progress||0)}%`,g?.title||tr('No active goal','بدون هدف فعال'),tr('milestones','مایلستون')],['countdown',tr('Countdown','شمارش‌معکوس'),cd?`${digits(Math.ceil((cd.targetUtc-now())/day))} ${tr('days','روز')}`:'—',cd?.title||tr('No countdown','موردی نیست'),fmtDate(cd?.targetUtc||0,true)],['calendar',tr('Calendar','تقویم'),fmtDate(now(),true),`${digits(today.length)} ${tr('today','امروز')}`,state.settings.calendar],['week',tr('Week','هفته'),`${digits(state.tasks.filter(t=>!t.completed&&t.startUtc>=now()-day&&t.startUtc<=now()+7*day).length)} ${tr('plans','برنامه')}`,tr('Next 7 days','۷ روز آینده'),tr('weekly overview','نمای هفتگی')],['quadrant',tr('Quadrant','چهارخانه'),`Q1 ${digits(q[0])} · Q2 ${digits(q[1])}`,`Q3 ${digits(q[2])} · Q4 ${digits(q[3])}`,tr('priority map','نقشه اولویت')],['mood',tr('Mood','حال‌وهوا'),mood,latest?.title||tr('No check-in yet','هنوز ثبت نشده'),latest?.dateKey||'—'],['stats',tr('Statistics','آمار'),`${digits(Math.round(done/total*100))}%`,tr('completion today','تکمیل امروز'),`${digits(focusMinutes(7))}m focus`],['joy','JOY',`Lv ${digits(state.joy.level||1)} · ${digits(state.joy.coins||0)}◇`,`${digits(state.joy.energy||0)}% ${tr('energy','انرژی')}`,state.joy.mood||'happy']]}
function renderWidgets(){const cards=widgetCards();return `${pageHead(tr('A complete desktop widget studio','استودیوی کامل ویجت دسکتاپ'),tr('Ten live widgets read the same local data: plans, calendar, focus, goals, mood, statistics and JOY.','ده ویجت زنده همان داده محلی را می‌خوانند: برنامه، تقویم، تمرکز، هدف، حال‌وهوا، آمار و JOY.'))}<div class="widget-toolbar"><span class="card-sub">${tr('Default widget size','اندازه پیش‌فرض ویجت')}:</span>${[['small',tr('Small','کوچک')],['medium',tr('Medium','متوسط')],['wide',tr('Wide','عریض')]].map(([v,l])=>`<button class="widget-size-chip ${state.settings.widgetSize===v?'active':''}" data-widget-size="${v}">${esc(l)}</button>`).join('')}</div><div class="widget-gallery">${cards.map(([k,h,v,n,meta])=>`<div class="card widget-preview"><div class="preview-window"><div class="small">PlanJoy · ${esc(h)}</div><div class="big">${esc(state.settings.widgetPrivacy?'•••':v)}</div><div class="small">${esc(state.settings.widgetPrivacy?tr('Details hidden','جزئیات مخفی است'):n)}</div><div class="small">${esc(meta||'')}</div></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:11px"><strong>${esc(h)}</strong><button class="btn primary small" data-action="open-widget" data-widget="${k}">${tr('Open widget','بازکردن ویجت')}</button></div></div>`).join('')}</div><div class="grid grid-2" style="margin-top:14px"><div class="card pad"><div class="setting-row"><div class="grow"><div class="setting-title">${tr('Hide sensitive widget details','مخفی‌کردن جزئیات ویجت')}</div><div class="setting-desc">${tr('Keep progress visible while hiding titles on shared screens.','پیشرفت دیده می‌شود اما عنوان‌ها روی صفحه مشترک پنهان می‌شوند.')}</div></div>${switchHtml('widgetPrivacy',state.settings.widgetPrivacy)}</div></div><div class="card pad"><div class="setting-title">${tr('Widget opacity','شفافیت ویجت')}</div><input type="range" data-widget-opacity min="0.72" max="1" step="0.02" value="${state.settings.widgetOpacity??1}" style="width:100%;margin-top:12px"></div></div>`}
'''
